"""Tests for the DTW cost matrix containers."""

import numpy as np
import pytest

from darts.dataprocessing.dtw.cost_matrix import (
    CostMatrix,
    DenseCostMatrix,
    SparseCostMatrix,
)
from darts.dataprocessing.dtw.window import CRWindow, NoWindow


def sparse_window() -> CRWindow:
    """A 6 x 6 window with only 6 active cells (density < 0.5)."""
    window = CRWindow(6, 6)
    window.add_range(1, 1, 4)
    window.add_range(2, 2, 5)
    return window


def dense_window() -> CRWindow:
    """A 4 x 4 window covering every cell (density > 0.5)."""
    window = CRWindow(4, 4)
    for column in range(1, 5):
        window.add_range(column, 1, 5)
    return window


class TestCostMatrixBase:
    def test_cost_matrix_is_abstract(self):
        with pytest.raises(TypeError):
            CostMatrix()

    def test_dense_matrix_is_a_numpy_array_and_cost_matrix(self):
        matrix = DenseCostMatrix(3, 2)
        assert isinstance(matrix, np.ndarray)
        assert isinstance(matrix, CostMatrix)

    def test_sparse_matrix_is_a_cost_matrix(self):
        assert isinstance(SparseCostMatrix(sparse_window()), CostMatrix)


class TestFromWindow:
    def test_window_covering_grid_produces_dense_matrix(self):
        window = NoWindow()
        window.init_size(3, 3)
        matrix = CostMatrix._from_window(window)
        assert isinstance(matrix, DenseCostMatrix)
        assert (matrix.n, matrix.m) == (3, 3)
        assert matrix.shape == (4, 4)

    def test_sparse_window_produces_sparse_matrix(self):
        window = sparse_window()
        matrix = CostMatrix._from_window(window)
        assert isinstance(matrix, SparseCostMatrix)
        assert (matrix.n, matrix.m) == (6, 6)
        assert matrix.window is window

    def test_dense_cr_window_produces_dense_matrix(self):
        matrix = CostMatrix._from_window(dense_window())
        assert isinstance(matrix, DenseCostMatrix)
        assert matrix.shape == (5, 5)


class TestDenseCostMatrix:
    @pytest.fixture
    def matrix(self):
