        np.testing.assert_array_equal(matrix.to_dense(), np.full((3, 2), 2.0))


class TestSparseCostMatrix:
    @pytest.fixture
    def window(self):
        return sparse_window()

    @pytest.fixture
    def matrix(self, window):
        return SparseCostMatrix(window)

    def test_dimensions_and_backing_window(self, matrix, window):
        assert (matrix.n, matrix.m) == (6, 6)
        assert matrix.window is window

    def test_new_matrix_is_filled_with_infinity(self, matrix):
        for elem in matrix:
            assert matrix[elem] == np.inf

    def test_iteration_matches_window(self, matrix, window):
        assert list(matrix) == list(window)
        assert len(list(matrix)) == 6

    def test_getitem_returns_inf_outside_window(self, matrix, window):
        cells = set(window)
        for i in range(1, 7):
            for j in range(1, 7):
                if (i, j) not in cells:
                    assert matrix[i, j] == np.inf

    def test_set_and_get_roundtrip_inside_window(self, matrix):
        matrix[1, 1] = 1.5
        matrix[2, 4] = -3.0
        assert matrix[1, 1] == pytest.approx(1.5)
        assert matrix[2, 4] == pytest.approx(-3.0)
        # neighbours are untouched
        assert matrix[1, 2] == np.inf

    def test_fill_sets_only_active_cells(self, matrix, window):
        matrix.fill(5.0)
        for i, j in window:
            assert matrix[i, j] == pytest.approx(5.0)
        assert matrix[5, 5] == np.inf
        assert matrix[3, 1] == np.inf

    def test_fill_with_infinity_keeps_matrix_cleared(self, matrix):
        matrix.fill(np.inf)
        assert all(matrix[elem] == np.inf for elem in matrix)

    def test_to_dense_shape_and_padding(self, matrix, window):
        matrix.fill(1.0)
        dense = matrix.to_dense()
        assert dense.shape == (6, 6)

        cells = set(window)
        for i in range(6):
            for j in range(6):
                if (i + 1, j + 1) in cells:
                    assert dense[i, j] == pytest.approx(1.0)
                else:
                    assert dense[i, j] == np.inf

    def test_to_dense_agrees_with_getitem_after_updates(self, matrix, window):
        for idx, elem in enumerate(window):
            matrix[elem] = float(idx)
        dense = matrix.to_dense()
        for i, j in window:
            assert dense[i - 1, j - 1] == pytest.approx(matrix[i, j])

"""Tests for the internal DTW building blocks in ``darts.dataprocessing.dtw.dtw``."""

import numpy as np
import pytest

from darts.dataprocessing.dtw.cost_matrix import (
    CostMatrix,
    DenseCostMatrix,
    SparseCostMatrix,
)
from darts.dataprocessing.dtw.dtw import (
    _default_distance_multi,
    _default_distance_uni,
    _down_sample,
    _dtw_cost_matrix,
    _dtw_path,
    _expand_window,
    _fast_dtw,
)
from darts.dataprocessing.dtw.window import CRWindow, NoWindow, SakoeChiba


def exact_cost(x: np.ndarray, y: np.ndarray) -> CostMatrix:
    window = NoWindow()
    window.init_size(len(x), len(y))
    return _dtw_cost_matrix(x, y, _default_distance_uni, window)


class TestDefaultDistances:
    @pytest.mark.parametrize(
        "x,y,expected", [(1.0, 4.0, 3.0), (2.0, 2.0, 0.0), (-1.5, 1.0, 2.5)]
    )
    def test_univariate_distance_is_absolute_difference(self, x, y, expected):
        assert _default_distance_uni(x, y) == pytest.approx(expected)

    def test_multivariate_distance_sums_component_distances(self):
        x = np.array([1.0, 2.0, -3.0])
        y = np.array([0.0, 2.0, 1.0])
        assert _default_distance_multi(x, y) == pytest.approx(1.0 + 0.0 + 4.0)

    def test_multivariate_distance_identical_vectors(self):
        x = np.array([1.0, 2.0])
        assert _default_distance_multi(x, x) == pytest.approx(0.0)


class TestDownSample:
    def test_even_length_is_pairwise_mean(self):
        high_res = np.array([0.0, 2.0, 3.0, 5.0])
        np.testing.assert_allclose(_down_sample(high_res), [1.0, 4.0])

    def test_odd_length_duplicates_last_value_before_halving(self):
        high_res = np.array([0.0, 2.0, 3.0, 5.0, 7.0])
        np.testing.assert_allclose(_down_sample(high_res), [1.0, 4.0, 7.0])

    @pytest.mark.parametrize("length", [1, 2, 3, 7, 8])
    def test_output_length_is_half_rounded_up(self, length):
        low_res = _down_sample(np.arange(float(length)))
        assert len(low_res) == -(-length // 2)

    def test_output_is_one_dimensional(self):
        assert _down_sample(np.arange(6.0)).ndim == 1


class TestDtwCostMatrix:
    def test_borders_are_infinite(self):
        matrix = exact_cost(np.array([0.0, 1.0]), np.array([0.0, 2.0]))
        assert matrix[0, 0] == pytest.approx(0.0)
        assert np.all(matrix[0, 1:] == np.inf)
        assert np.all(matrix[1:, 0] == np.inf)

    def test_values_match_dynamic_programming_recursion(self):
        # x = [0, 1], y = [0, 2]
        # cost(1,1) = 0, cost(1,2) = 2, cost(2,1) = 1, cost(2,2) = 1 + min(2, 1, 0) = 1
        matrix = exact_cost(np.array([0.0, 1.0]), np.array([0.0, 2.0]))
        np.testing.assert_allclose(matrix.to_dense(), [[0.0, 2.0], [1.0, 1.0]])

    def test_custom_distance_is_used(self):
        squared = lambda a, b: (a - b) ** 2  # noqa: E731
        window = NoWindow()
        window.init_size(2, 2)
        matrix = _dtw_cost_matrix(
            np.array([0.0, 2.0]), np.array([0.0, 2.0]), squared, window
        )
        # (1,2) = 4 and (2,1) = 4, diagonal is free
        np.testing.assert_allclose(matrix.to_dense(), [[0.0, 4.0], [4.0, 0.0]])

    def test_only_window_cells_are_evaluated(self):
        window = SakoeChiba(1)
        window.init_size(5, 5)
        matrix = _dtw_cost_matrix(
            np.arange(5.0), np.arange(5.0) + 1.0, _default_distance_uni, window
        )
        active = set(window)
        for i in range(1, 6):
            for j in range(1, 6):
                if (i, j) in active:
                    assert np.isfinite(matrix[i, j])
                else:
                    assert matrix[i, j] == np.inf

    def test_matrix_type_follows_window_density(self):
        narrow = CRWindow(8, 8)
        narrow.add_range(1, 1, 2)
        matrix = _dtw_cost_matrix(
            np.arange(8.0), np.arange(8.0), _default_distance_uni, narrow
        )
        assert isinstance(matrix, SparseCostMatrix)
        wide = NoWindow()
        wide.init_size(3, 3)
        matrix = _dtw_cost_matrix(
            np.arange(3.0), np.arange(3.0), _default_distance_uni, wide
        )
        assert isinstance(matrix, DenseCostMatrix)


class TestDtwPath:
    def test_hand_computed_path(self):
        matrix = DenseCostMatrix(2, 2)
        matrix.fill(np.inf)
        matrix[1, 1] = 0.0
        matrix[1, 2] = 1.0
        matrix[2, 1] = 1.0
        matrix[2, 2] = 0.0
        np.testing.assert_array_equal(_dtw_path(matrix), [[0, 0], [1, 1]])

    def test_path_may_move_along_a_single_axis(self):
        # x = [1, 2, 3] vs y = [2, 3, 4]: no useful diagonal start
        path = _dtw_path(
            exact_cost(np.array([1.0, 2.0, 3.0]), np.array([2.0, 3.0, 4.0]))
        )
        np.testing.assert_array_equal(path, [[0, 0], [1, 0], [2, 1], [2, 2]])

    @pytest.mark.parametrize("length", [1, 2, 5])
    def test_identical_series_align_on_diagonal(self, length):
        values = np.arange(1.0, length + 1.0)
        path = _dtw_path(exact_cost(values, values))
        np.testing.assert_array_equal(path, np.stack([np.arange(length)] * 2, axis=1))

    def test_path_is_monotonic_and_starts_and_ends_at_corners(self):
        rng = np.random.RandomState(42)
        x = rng.randn(9)
        y = rng.randn(7)
        path = _dtw_path(exact_cost(x, y))

        assert path.shape[1] == 2
        np.testing.assert_array_equal(path[0], [0, 0])
        np.testing.assert_array_equal(path[-1], [len(x) - 1, len(y) - 1])
        steps = np.diff(path, axis=0)
        assert np.all(steps >= 0)
        assert np.all(steps <= 1)
        assert np.all(steps.sum(axis=1) >= 1)


class TestExpandWindow:
    def test_returns_window_of_requested_size(self):
        window = _expand_window(np.array([[0, 0]]), 4, 4, radius=0)
        assert isinstance(window, CRWindow)
        assert (window.n, window.m) == (4, 4)

    def test_all_cells_stay_inside_grid(self):
        window = _expand_window(np.array([[0, 0], [1, 1], [2, 2]]), 6, 5, radius=2)
        cells = list(window)
        assert cells
        assert all(1 <= i <= 6 and 1 <= j <= 5 for i, j in cells)

    def test_upsampled_low_resolution_path_is_covered(self):
        path = np.array([[0, 0], [1, 1], [2, 2]])
        for radius in (0, 1):
            cells = set(_expand_window(path, 5, 5, radius))
            for i, j in path:
                assert (2 * i + 1, 2 * j + 1) in cells

    def test_single_cell_expands_to_a_block(self):
        cells = set(_expand_window(np.array([[0, 0]]), 4, 4, radius=0))
        assert {(1, 1), (1, 2), (2, 1), (2, 2)} <= cells

    def test_larger_radius_only_adds_cells(self):
        path = np.array([[0, 0], [1, 1], [2, 2]])
        narrow = set(_expand_window(path, 5, 5, radius=0))
        wide = set(_expand_window(path, 5, 5, radius=1))
        assert narrow <= wide
        assert len(wide) > len(narrow)

    def test_large_radius_expands_columns_over_full_height(self):
        cells = set(_expand_window(np.array([[0, 0]]), 4, 4, radius=10))
        for column in (1, 2, 3):
            assert all((column, row) in cells for row in range(1, 5))


class TestFastDtw:
    def test_negative_radius_falls_back_to_exact_evaluation(self):
        rng = np.random.RandomState(11)
        x, y = rng.randn(20), rng.randn(20)
        approximate = _fast_dtw(x, y, _default_distance_uni, -1)
        expected = exact_cost(x, y)
        assert approximate[20, 20] == pytest.approx(expected[20, 20])

    @pytest.mark.parametrize("radius", [0, 1, 2, 4])
    def test_terminal_cell_is_reachable(self, radius):
        rng = np.random.RandomState(11)
        x, y = rng.randn(20), rng.randn(20)
        matrix = _fast_dtw(x, y, _default_distance_uni, radius)
        assert np.isfinite(matrix[20, 20])

    @pytest.mark.parametrize("radius", [0, 1, 2, 4])
    def test_approximation_never_beats_exact_solution(self, radius):
        rng = np.random.RandomState(11)
        x, y = rng.randn(20), rng.randn(20)
        exact = exact_cost(x, y)[20, 20]
        approximate = _fast_dtw(x, y, _default_distance_uni, radius)[20, 20]
        assert approximate >= exact * (1 - 1e-5)

    def test_identical_series_have_zero_cost(self):
        values = np.sin(np.arange(16.0))
        matrix = _fast_dtw(values, values, _default_distance_uni, 1)
        assert matrix[16, 16] == pytest.approx(0.0)
        np.testing.assert_array_equal(
            _dtw_path(matrix), np.stack([np.arange(16)] * 2, axis=1)
        )

    def test_small_series_use_full_grid(self):
        # min_size is radius + 2; series shorter than that are solved exactly
        x, y = np.array([0.0, 1.0]), np.array([1.0, 2.0])
        matrix = _fast_dtw(x, y, _default_distance_uni, 5)
        np.testing.assert_allclose(matrix.to_dense(), exact_cost(x, y).to_dense())

