import numpy as np
import pandas as pd
import pytest

from darts import TimeSeries


@pytest.fixture
def make_series():
    """Build small deterministic ``TimeSeries`` objects for dataset tests."""

    def _make(
        values,
        *,
        columns=None,
        static_covariates=None,
        start=None,
    ):
        values = np.asarray(values, dtype=np.float64)
        if values.ndim == 1:
            values = values[:, None]
        if start is None:
            return TimeSeries.from_values(
                values,
                columns=columns,
                static_covariates=static_covariates,
            )
        times = pd.date_range(start=start, periods=len(values), freq="D")
        return TimeSeries.from_times_and_values(
            times,
            values,
            columns=columns,
            static_covariates=static_covariates,
        )

    return _make
